-- Traductions corrigées et textes ajoutés par les correctifs UX des parcours de conversion (10/11/2026). Ne s'applique
-- qu'aux lignes déjà présentes. Une valeur n'est remplacée QUE si elle est encore l'ancienne (une saisie de l'équipe n'est
-- jamais écrasée) ; un texte nouveau n'est ajouté que s'il manque. Créoles HT et GCF : aucune correction ; leurs textes
-- nouveaux sont à faire relire par un locuteur.

-- 1. Anglais du billet : « Go, return », « locations » (lieux), dates d'arrivée et de départ distinctes de la ville de départ
update public.contenu_site set valeur = jsonb_set(valeur, '{dates,aller}', to_jsonb($t$Outbound$t$::text)) where cle = 'EN:fr.devisPage' and valeur #>> '{dates,aller}' = $t$Go$t$;
update public.contenu_site set valeur = jsonb_set(valeur, '{lieux,titreVide}', to_jsonb($t$Your places$t$::text)) where cle = 'EN:fr.devisPage' and valeur #>> '{lieux,titreVide}' = $t$Your locations$t$;
update public.contenu_site set valeur = jsonb_set(valeur, '{lieux,trou}', to_jsonb($t$which places?$t$::text)) where cle = 'EN:fr.devisPage' and valeur #>> '{lieux,trou}' = $t$which locations?$t$;
